/**
 * Sanitizes LLM outputs by removing internal reasoning / chain-of-thought blocks.
 * Handles tags such as <thinking>, <thought>, and <reasoning> from models like
 * DeepSeek-R1, Gemini Thinking, and Claude with Extended Thinking.
 *
 * @param {string} text - Raw text generated by an AI model.
 * @returns {string} Cleaned text suitable for display to end users.
 */
export function stripThinking(text) {
  if (typeof text !== 'string') return '';
  return text
    // Strip balanced thinking, thought, and reasoning tags (case-insensitive)
    .replace(/<thinking>[\s\S]*?<\/thinking>\s*/gi, '')
    .replace(/<thought>[\s\S]*?<\/thought>\s*/gi, '')
    .replace(/<reasoning>[\s\S]*?<\/reasoning>\s*/gi, '')
    // Clean any stray, unclosed, or orphaned opening/closing tags
    .replace(/<\/?(?:thinking|thought|reasoning)>/gi, '')
    .trim();
}

